#pragma once
#include "AutoFit.h"
#include "PresetTraits.h"
#include <cstring>
namespace nova {
struct VariationLocks {bool tone=false,envelope=false,effects=false,motion=false;};
inline Params varyPatch(Params p,int strength,VariationLocks lock,uint32_t seed){std::mt19937 rng(seed);std::uniform_real_distribution<float> unit(-1,1);float amount=std::array<float,3>{.045f,.13f,.27f}[std::clamp(strength,0,2)];auto d=[&]{return unit(rng)*amount;};
 if(!lock.tone){p.cutoff=std::clamp(p.cutoff*std::exp(d()*2),30.f,20000.f);p.resonance=std::clamp(p.resonance+d(),0.f,.88f);p.fm=std::clamp(p.fm+d(),0.f,1.f);p.mix=std::clamp(p.mix+d(),0.f,1.f);p.spectralTone=std::clamp(p.spectralTone+d(),-1.f,1.f);p.character=std::clamp(p.character+d(),0.f,1.f);}
 if(!lock.envelope){p.attack=std::clamp(p.attack*std::exp(d()*3),.001f,5.f);p.decay=std::clamp(p.decay*std::exp(d()*3),.005f,5.f);p.sustain=std::clamp(p.sustain+d(),0.f,1.f);p.release=std::clamp(p.release*std::exp(d()*3),.005f,8.f);p.spectralTime=std::clamp(p.spectralTime*std::exp(d()),.25f,4.f);}
 if(!lock.effects){p.drive=std::clamp(p.drive+d()*.35f,0.f,.65f);p.delay=std::clamp(p.delay+d()*.35f,0.f,.6f);p.reverb=std::clamp(p.reverb+d()*.35f,0.f,.6f);p.eqLow=std::clamp(p.eqLow+d()*6,-12.f,12.f);p.eqHigh=std::clamp(p.eqHigh+d()*6,-12.f,12.f);}
 if(!lock.motion){p.movement=std::clamp(p.movement+d(),0.f,1.f);p.lfoRate=std::clamp(p.lfoRate*std::exp(d()),.03f,15.f);p.modRate=std::clamp(p.modRate*std::exp(d()),.03f,15.f);}return p;}
inline void keepPresetLocks(Params& d,const Params& s,bool fx,bool volume){if(fx){d.drive=s.drive;d.chorus=s.chorus;d.chorusRate=s.chorusRate;d.delay=s.delay;d.delayTime=s.delayTime;d.feedback=s.feedback;d.reverb=s.reverb;d.room=s.room;d.eqLow=s.eqLow;d.eqHigh=s.eqHigh;d.space=s.space;d.driveOn=s.driveOn;d.chorusOn=s.chorusOn;d.delayOn=s.delayOn;d.reverbOn=s.reverbOn;d.eqOn=s.eqOn;}if(volume){d.master=s.master;d.boost=s.boost;d.presetTrim=s.presetTrim;}}
inline double patchSimilarity(const Params& a,const Params& b){auto x=toGenes(a),y=toGenes(b);double score=a.engine==b.engine?0:.45;for(int i:{0,1,4,8,9,10,11,12,13,14,15,18,19,21,24})score+=std::abs(x[i]-y[i])/(i>=12&&i<=15?5.:15.);return score+std::abs(a.spectralTone-b.spectralTone)*.15+std::abs(a.character-b.character)*.1;}
inline const char* controlHelp(const char* id){const std::pair<const char*,const char*> help[]={
 {"cutoff","Brillo: abre el filtro para dejar pasar mas agudos."},{"resonance","Resalta las frecuencias alrededor del filtro."},{"attack","Entrada de la nota: menor tiempo da un golpe mas rapido."},{"decay","Tiempo desde el ataque hasta el nivel sostenido."},{"sustain","Nivel que se mantiene al sostener la tecla."},{"release","Tiempo que tarda el sonido en apagarse al soltar la tecla."},{"fine","Afinacion global en cents; cero corresponde a las notas MIDI."},{"root","Nota de referencia del modelo. No transpone las notas que tocas."},{"tracking","Movimiento tonal del modelo; cero elimina el movimiento detectado."},{"fm","Cambia los armonicos; en cuerda cambia el punto de pulsacion."},{"mix","Mezcla de osciladores o recorrido de wavetable."},{"detune","Separa las voces en afinacion para ensancharlas."},{"transpose","Intervalo del segundo oscilador en semitonos."},{"sub","Agrega un oscilador una octava mas grave."},{"noise","Agrega aire o ruido al timbre."},{"envamount","Cuanto abre o cierra el filtro la envolvente."},{"lforate","Velocidad del movimiento periodico del filtro."},{"lfodepth","Cantidad de movimiento del filtro; no es vibrato de afinacion."},{"drive","Saturacion: agrega armonicos y puede aumentar el nivel."},{"delay","Cantidad de repeticiones mezcladas con el sonido directo."},{"delaytime","Separacion en segundos entre repeticiones."},{"feedback","Cuanto se vuelve a repetir el eco."},{"reverb","Cantidad de ambiente mezclado con el sonido."},{"room","Tamano y duracion del ambiente."},{"chorus","Mezcla de voces moduladas para ensanchar el sonido."},{"chorusrate","Velocidad del movimiento de chorus."},{"eqlow","Sube o baja los graves."},{"eqhigh","Sube o baja los agudos."},{"spread","Anchura estereo de los osciladores compatibles."},{"master","Nivel del instrumento antes de la ganancia manual."},{"spectime","Estira o acorta la evolucion de los parciales."},{"spectone","Balance entre parciales graves y agudos."},{"residual","Cantidad de aire y ruido sintetizado del modelo."}};for(auto e:help)if(std::strcmp(e.first,id)==0)return e.second;return "Doble clic recupera el valor inicial.";}
}
